        data: {"result": {"minY": 0.13333333333333333, "minX": 1.75211778E12, "maxY": 12.8, "series": [{"data": [[1.7521179E12, 12.8], [1.75211784E12, 9.7], [1.75211802E12, 9.233333333333333], [1.75211796E12, 12.266666666666667], [1.75211778E12, 1.0833333333333333]], "isOverall": false, "label": "Transaction-success", "isController": false}, {"data": [[1.75211802E12, 0.23333333333333334], [1.75211796E12, 0.13333333333333333]], "isOverall": false, "label": "Transaction-failure", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 60000, "maxX": 1.75211802E12, "title": "Total Transactions Per Second"}},
